    // ----- PEM（PUBLIC KEY）导入 -----
    //
    // PEM 入口只负责严格的外壳与 Base64 解析，还原出 DER 后完全复用
    // from_spki_der，因此这一组测试的重心是：
    // 1. PEM 与 DER 两个入口对同一把公钥完全等价；
    // 2. PEM 外壳的严格边界（标记、行结束、正文、块的数量）；
    // 3. 标准 Base64 的严格解码（字母表、填充、未使用位）；
    // 4. 还原出的 DER 损坏时报 Malformed，完整但算法不同时报
    //    UnsupportedAlgorithm——分类规则与 DER 入口一致。

    /// RFC 8410 示例 SPKI 的标准 Base64（独立依据：python3 base64 对
    /// RFC8410_SPKI 的编码结果），60 个字符、末尾一个填充符。
    const RFC8410_PEM_BODY: &str =
        "MCowBQYDK2VwAyEA11qYAYKxCrfVS/7TyWQHOg7hcvPapiMlrwIaaPcHURo=";

    /// 把若干正文行按给定行结束拼成一份完整 PEM；`tail` 控制尾标记之后
    /// 的内容（无换行、LF、CRLF 或其他用于反例的字节）。
    fn pem_from_lines(lines: &[&[u8]], line_eol: &[u8], tail: &[u8]) -> Vec<u8> {
        let mut out = PEM_BEGIN.to_vec();
        out.extend_from_slice(line_eol);
        for line in lines {
            out.extend_from_slice(line);
            out.extend_from_slice(line_eol);
        }
        out.extend_from_slice(PEM_END);
        out.extend_from_slice(tail);
        out
    }

    /// 单行正文、行间 LF、尾标记后无换行的标准 PEM。
    fn pem_single(body: &[u8]) -> Vec<u8> {
        pem_from_lines(&[body], b"\n", b"")
    }

    #[test]
    fn pem_imports_rfc8410_example_and_matches_der_entry() {
        // 三种合法收尾：无换行、一个 LF、一个 CRLF——导入结果完全一致。
        let no_tail = pem_single(RFC8410_PEM_BODY.as_bytes());
        let lf_tail = pem_from_lines(&[RFC8410_PEM_BODY.as_bytes()], b"\n", b"\n");
        let crlf_tail = pem_from_lines(&[RFC8410_PEM_BODY.as_bytes()], b"\r\n", b"\r\n");

        for pem in [&no_tail, &lf_tail, &crlf_tail] {
            let from_pem = Ed25519PublicKey::from_spki_pem(pem).unwrap();
            let from_der = Ed25519PublicKey::from_spki_der(RFC8410_SPKI).unwrap();
            // 同一把公钥从 PEM 或 DER 导入：原始 32 字节相同，按值比较相等。
            assert_eq!(from_pem, from_der);
            assert_eq!(from_pem.as_bytes(), &RFC8410_SPKI[12..]);
            assert_eq!(from_pem.to_hex(), RFC8410_KEY_HEX);
            assert_eq!(format!("{from_pem}"), RFC8410_KEY_HEX);
            assert_ne!(
                from_pem.to_hex(),
                digest_reader(&RFC8410_SPKI[12..]).unwrap().to_hex()
            );
        }
    }

    #[test]
    fn pem_hex_is_64_lowercase_chars_and_keeps_leading_zeros() {
        // 独立依据：python3 base64 对“前导 0x00、末尾 0xff”的规范 SPKI
        // 的编码结果。
        let mut raw = [0u8; 32];
        raw[0] = 0x00;
        raw[1] = 0x0a;
        raw[31] = 0xff;
        let pem = pem_single(b"MCowBQYDK2VwAyEAAAoAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAP8=");
        let key = Ed25519PublicKey::from_spki_pem(&pem).unwrap();
        assert_eq!(key.as_bytes(), &raw);

        let hex = key.to_hex();
        assert_eq!(hex.len(), 64);
        assert!(hex.starts_with("000a"));
        assert!(hex.ends_with("ff"));
        assert!(hex.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
        assert!(!hex.chars().any(char::is_whitespace));
    }

    #[test]
    fn pem_body_may_be_one_or_many_lines_with_lf_or_crlf() {
        let body = RFC8410_PEM_BODY.as_bytes();
        let expected = Ed25519PublicKey::from_spki_der(RFC8410_SPKI).unwrap();

        // 任意位置切分成多行，全部用 LF。
        for cut in [16usize, 32, 48, 59] {
            let lines: [&[u8]; 2] = [&body[..cut], &body[cut..]];
            let pem = pem_from_lines(&lines, b"\n", b"\n");
            assert_eq!(Ed25519PublicKey::from_spki_pem(&pem).unwrap(), expected);
        }
        // 切到只剩填充符独占一行（cut=59，第二行就是 "="）：拼回完整串
        // 后仍是合法的标准 Base64，必须接受，而不是把行内的 `=` 误判为
        // 非法字符。
        let pad_on_own_line = pem_from_lines(&[&body[..59], b"="], b"\n", b"");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pad_on_own_line).unwrap(),
            expected
        );
        // 全部行结束（含首标记之后）都用 CRLF，尾标记后无换行。
        let all_crlf = pem_from_lines(
            &[&body[..32], &body[32..]],
            b"\r\n",
            b"",
        );
        assert_eq!(Ed25519PublicKey::from_spki_pem(&all_crlf).unwrap(), expected);
        // 行间混用 LF 与 CRLF，尾标记后跟 CRLF。
        let mut mixed = PEM_BEGIN.to_vec();
        mixed.extend_from_slice(b"\r\n");
        mixed.extend_from_slice(&body[..16]);
        mixed.extend_from_slice(b"\r\n");
        mixed.extend_from_slice(&body[16..]);
        mixed.extend_from_slice(b"\n");
        mixed.extend_from_slice(PEM_END);
        mixed.extend_from_slice(b"\r\n");
        assert_eq!(Ed25519PublicKey::from_spki_pem(&mixed).unwrap(), expected);
    }

    #[test]
    fn pem_requires_exactly_one_block_with_nothing_around_it() {
        let valid = pem_from_lines(&[RFC8410_PEM_BODY.as_bytes()], b"\n", b"\n");

        // 空输入。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(b"").unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 首标记之前有任何内容（字节、空白、BOM、换行）。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&[&b"x"[..], &valid].concat()).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&[&b"\n"[..], &valid].concat()).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&[&[0xef, 0xbb, 0xbf][..], &valid].concat())
                .unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 尾标记之后有多余内容：杂散字节、额外 LF、空行、单独 CR。
        let no_tail = pem_single(RFC8410_PEM_BODY.as_bytes());
        for tail in [&b"x"[..], &b"\n\n"[..], &b"\nmore"[..], &b"\r"[..], &b"\n\n"[..]] {
            let mut pem = no_tail.clone();
            pem.extend_from_slice(tail);
            assert_eq!(
                Ed25519PublicKey::from_spki_pem(&pem).unwrap_err(),
                ImportPublicKeyError::Malformed,
                "tail {tail:?} must be rejected"
            );
        }
        // 两个 LF / 两个 CRLF 都不是“只有一个换行”。
        let mut double_lf = no_tail.clone();
        double_lf.extend_from_slice(b"\n\n");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&double_lf).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        let mut double_crlf = no_tail.clone();
        double_crlf.extend_from_slice(b"\r\n\r\n");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&double_crlf).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 第二个块：绝不只取第一个块而忽略后续内容。
        let two_blocks = [valid.clone(), valid].concat();
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&two_blocks).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    #[test]
    fn pem_rejects_other_labels_and_label_mismatch() {
        let body = RFC8410_PEM_BODY.as_bytes();
        // PRIVATE KEY、CERTIFICATE 等其他标签一律不接受，即使正文是一份
        // 合法的 Ed25519 SubjectPublicKeyInfo。
        let private = pem_from_lines_custom(
            b"-----BEGIN PRIVATE KEY-----",
            &[body],
            b"-----END PRIVATE KEY-----",
        );
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&private).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        let cert = pem_from_lines_custom(
            b"-----BEGIN CERTIFICATE-----",
            &[body],
            b"-----END CERTIFICATE-----",
        );
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&cert).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 首尾标签不成对：以 PUBLIC KEY 开始却以其他标签结束。
        let mismatched = pem_from_lines_custom(PEM_BEGIN, &[body], b"-----END CERTIFICATE-----");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&mismatched).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 缺尾标记（正文后只有行结束，输入直接结束）。
        let mut no_end = PEM_BEGIN.to_vec();
        no_end.extend_from_slice(b"\n");
        no_end.extend_from_slice(body);
        no_end.extend_from_slice(b"\n");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&no_end).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 只有尾标记、没有首标记。
        let mut no_begin = body.to_vec();
        no_begin.extend_from_slice(b"\n");
        no_begin.extend_from_slice(PEM_END);
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&no_begin).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 尾标记没有独占一行（直接接在正文之后）。
        let mut end_glued = PEM_BEGIN.to_vec();
        end_glued.extend_from_slice(b"\n");
        end_glued.extend_from_slice(body);
        end_glued.extend_from_slice(PEM_END);
        end_glued.push(b'\n');
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&end_glued).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    /// 与 [`pem_from_lines`] 相同的拼法，但首尾标记可替换成任意标签，
    /// 专用于构造其他标签的反例。
    fn pem_from_lines_custom(begin: &[u8], lines: &[&[u8]], end: &[u8]) -> Vec<u8> {
        let mut out = begin.to_vec();
        out.extend_from_slice(b"\n");
        for line in lines {
            out.extend_from_slice(line);
            out.extend_from_slice(b"\n");
        }
        out.extend_from_slice(end);
        out.push(b'\n');
        out
    }

    #[test]
    fn pem_rejects_blank_lines_inline_whitespace_and_lone_cr() {
        let body = RFC8410_PEM_BODY.as_bytes();

        // 空正文：首标记之后直接是尾标记。
        let mut empty_body = PEM_BEGIN.to_vec();
        empty_body.extend_from_slice(b"\n");
        empty_body.extend_from_slice(PEM_END);
        empty_body.push(b'\n');
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&empty_body).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 首标记与正文之间的空行；正文两行之间的空行；正文与尾标记之间
        // 的空行。
        for pem in [
            [PEM_BEGIN, b"\n\n", body, b"\n", PEM_END, b"\n"].concat(),
            [PEM_BEGIN, b"\n", &body[..16], b"\n\n", &body[16..], b"\n", PEM_END, b"\n"].concat(),
            [PEM_BEGIN, b"\n", body, b"\n\n", PEM_END, b"\n"].concat(),
        ] {
            assert_eq!(
                Ed25519PublicKey::from_spki_pem(&pem).unwrap_err(),
                ImportPublicKeyError::Malformed,
                "blank lines must be rejected: {pem:?}"
            );
        }
        // 行内空格与制表符（行首、行中、行末）。
        for insertion in [
            [&b" "[..], body].concat(),
            [&body[..20], b" ", &body[20..]].concat(),
            [body, &b" \n"[..]].concat(),
            [&b"\t"[..], body].concat(),
            [&body[..10], b"\t", &body[10..]].concat(),
        ] {
            let pem = pem_single(&insertion);
            assert_eq!(
                Ed25519PublicKey::from_spki_pem(&pem).unwrap_err(),
                ImportPublicKeyError::Malformed,
                "inline whitespace must be rejected: {pem:?}"
            );
        }
        // 单独的 CR 不是可接受的行结束（首标记后、正文行之间、尾标记后）。
        let lone_cr_body = [PEM_BEGIN, b"\r", body, b"\r", PEM_END].concat();
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&lone_cr_body).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        let cr_between_lines =
            [PEM_BEGIN, b"\n", &body[..16], b"\r", &body[16..], b"\n", PEM_END].concat();
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&cr_between_lines).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    #[test]
    fn pem_rejects_non_base64_body_bytes() {
        let body = RFC8410_PEM_BODY.as_bytes();

        // URL 安全字母表（- 与 _）不是标准 Base64 字符。
        let mut url_safe = body.to_vec();
        url_safe[33] = b'_'; // 原字符是 '/'
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(&url_safe)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        let mut dash = body.to_vec();
        dash[10] = b'-';
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(&dash)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 其他非法字符。
        for bad in [b'!', b'@', b'#', b' ', 0x80, 0xff] {
            let mut corrupted = body.to_vec();
            corrupted[5] = bad;
            assert_eq!(
                Ed25519PublicKey::from_spki_pem(&pem_single(&corrupted)).unwrap_err(),
                ImportPublicKeyError::Malformed,
                "byte {bad:#x} must be rejected"
            );
        }
        // 缺少末尾填充（59 个字符，长度不是 4 的倍数）。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(&body[..59])).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 多出填充（61 个字符）。
        let mut extra_pad = body.to_vec();
        extra_pad.push(b'=');
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(&extra_pad)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 填充之后继续出现编码字符。
        let pad_then_more = b"AA==AAAA";
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(pad_then_more)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        let pad_in_last_group = b"AA=A";
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(pad_in_last_group)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 填充出现在非末尾的四元组中。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_single(b"AAA=AAAA")).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    #[test]
    fn standard_base64_decoder_is_strict_about_alphabet_padding_and_unused_bits() {
        // 合法向量（独立依据：python3 base64.b64encode 的结果）。
        assert_eq!(decode_standard_base64(b"").copied(), None); // 空串非法
        assert_eq!(
            decode_standard_base64(b"QUJD").as_deref(),
            Some(b"ABC".as_slice())
        );
        assert_eq!(
            decode_standard_base64(b"QUI=").as_deref(),
            Some(b"AB".as_slice())
        );
        assert_eq!(
            decode_standard_base64(b"QQ==").as_deref(),
            Some(b"A".as_slice())
        );
        assert_eq!(
            decode_standard_base64(RFC8410_PEM_BODY.as_bytes()).as_deref(),
            Some(RFC8410_SPKI.as_slice())
        );

        // 长度不是 4 的倍数：缺填充或多出字符。
        for bad in [&b"Q"[..], b"QUI", b"AAA", b"QQ=", b"A", &vec![b'A'; 7]] {
            assert_eq!(
                decode_standard_base64(bad),
                None,
                "non-multiple-of-4 input must fail: {bad:?}"
            );
        }
        // 填充位置或数量不规范。
        for bad in [
            &b"Q==="[..],
            b"=AAA",
            b"A===",
            b"====",
            b"AA=A",
            b"A=AA",
            b"AAA==",
            b"AA=X",
        ] {
            assert_eq!(decode_standard_base64(bad), None, "bad padding: {bad:?}");
        }
        // 末尾未使用位非零：RFC 4648 规定必须拒绝（python3 的解码器对这类
        // 输入较宽松，这里按规范严格处理）。
        assert_eq!(decode_standard_base64(b"AAB="), None); // 双字节量子末 8 位非零
        assert_eq!(decode_standard_base64(b"AR=="), None); // 单字节量子末 16 位非零
        // 而未使用位为零的等价编码接受。
        assert_eq!(decode_standard_base64(b"AAA=").as_deref(), Some(&[0u8, 0][..]));
        assert_eq!(decode_standard_base64(b"AA==").as_deref(), Some(&[0u8][..]));

        // 字母表之外的任何字符。
        for bad in [
            &b"AA-A"[..],
            b"AA_A",
            b"AA A",
            b"AA\nA",
            b"AA\tA",
            b"!!!=",
            &[b'A', b'A', b'A', 0x80],
        ] {
            assert_eq!(decode_standard_base64(bad), None, "bad alphabet: {bad:?}");
        }
    }

    #[test]
    fn pem_wrapping_a_corrupted_der_is_malformed() {
        // 截断的 DER（外层声明内容不完整）：Base64 本身合法，但还原出的
        // DER 损坏——报格式错误，不产生公钥对象。
        let truncated = pem_single(b"MCowBQYDK2VwAyEA11qYAYKxCrfVS/7TyWQHOg7hcvH");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&truncated).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 外层声明长度与实际不符。
        let bad_outer_len = pem_single(b"MCswBQYDK2VwAyEA11qYAYKxCrfVS/7TyWQHOg7hcvPapiMlrwIaaPcHURo=");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&bad_outer_len).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 位串声明长度与公钥内容不符。
        let bad_bs_len = pem_single(b"MCowBQYDK2VwAyAA11qYAYKxCrfVS/7TyWQHOg7hcvPapiMlrwIaaPcHURo=");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&bad_bs_len).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 完整对象之后多一个字节：Base64 长度恰为 3 的倍数所以没有填充，
        // 解码得到 45 字节，DER 入口必须拒绝多余字节。
        let trailing_der_byte =
            pem_single(b"MCowBQYDK2VwAyEA11qYAYKxCrfVS/7TyWQHOg7hcvPapiMlrwIaaPcHURoA");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&trailing_der_byte).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 裸公钥（32 字节）即便包进合法 PEM 外壳也不是 SPKI 容器。
        let raw_only = pem_single(
            base64_encode_for_test(&RFC8410_SPKI[12..]).as_bytes(),
        );
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&raw_only).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    /// 仅供测试构造反例：用一个最小的标准 Base64 编码器把任意字节包进
    /// PEM，预期这些输入在 DER 层面被拒绝。
    fn base64_encode_for_test(data: &[u8]) -> String {
        const ALPHABET: &[u8; 64] =
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut out = String::new();
        for chunk in data.chunks(3) {
            let b0 = u32::from(chunk[0]);
            let b1 = chunk.get(1).copied().map(u32::from);
            let b2 = chunk.get(2).copied().map(u32::from);
            let v = (b0 << 16) | (b1.unwrap_or(0) << 8) | b2.unwrap_or(0);
            out.push(ALPHABET[((v >> 18) & 0x3f) as usize] as char);
            out.push(ALPHABET[((v >> 12) & 0x3f) as usize] as char);
            match (b1, b2) {
                (Some(_), Some(_)) => {
                    out.push(ALPHABET[((v >> 6) & 0x3f) as usize] as char);
                    out.push(ALPHABET[(v & 0x3f) as usize] as char);
                }
                (Some(_), None) => {
                    out.push(ALPHABET[((v >> 6) & 0x3f) as usize] as char);
                    out.push('=');
                }
                _ => {
                    out.push('=');
                    out.push('=');
                }
            }
        }
        out
    }

    #[test]
    fn pem_of_other_algorithms_keeps_unsupported_classification_and_oid() {
        // 完整、规范的 Ed448（1.3.101.113）SPKI 包在 PEM 里：分类仍是
        // 算法不支持，OID 原样保留。
        let ed448_pem = pem_single(
            b"MEMwBQYDK2VxAzoARERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERERE",
        );
        match Ed25519PublicKey::from_spki_pem(&ed448_pem).unwrap_err() {
            ImportPublicKeyError::UnsupportedAlgorithm(oid) => {
                assert_eq!(oid.arcs(), &[1, 3, 101, 113]);
                assert_eq!(oid.to_string(), "1.3.101.113");
            }
            other => panic!("expected UnsupportedAlgorithm for Ed448 PEM, got {other:?}"),
        }
        // X25519（1.3.101.110）同理。
        let x25519_pem = pem_single(
            b"MCowBQYDK2VuAyEAQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkI=",
        );
        match Ed25519PublicKey::from_spki_pem(&x25519_pem).unwrap_err() {
            ImportPublicKeyError::UnsupportedAlgorithm(oid) => {
                assert_eq!(oid.arcs(), &[1, 3, 101, 110]);
            }
            other => panic!("expected UnsupportedAlgorithm for X25519 PEM, got {other:?}"),
        }
        // 但同属 Ed448 标识的 PEM，只要还原出的 DER 已截断，就必须报
        // 格式错误，不能因为读到了其他算法标识而改报算法不支持。
        let ed448_truncated = pem_single(b"MEMwBQYDK2VxAzoARERERERERERERERERERERERERE");
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&ed448_truncated).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    #[test]
    fn der_entry_still_rejects_pem_text() {
        // 兼容约束：DER 入口继续只接受 DER，PEM 文本（合法或损坏）一律
        // 拒绝，不做格式猜测。
        let pem = pem_from_lines(&[RFC8410_PEM_BODY.as_bytes()], b"\n", b"\n");
        assert_eq!(
            Ed25519PublicKey::from_spki_der(&pem).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 反向：PEM 入口也不接受裸 DER（没有 PEM 外壳）。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(RFC8410_SPKI).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

    #[test]
    fn pem_import_success_does_not_change_key_value_semantics() {
        // 两把内容不同的公钥都走 PEM 导入：按值不等；同一把的两种封装
        // （单行/多行、不同收尾）按值相等，Hash 也一致。
        let mut other_raw = [0u8; 32];
        other_raw.copy_from_slice(&RFC8410_SPKI[12..]);
        other_raw[31] ^= 0x01;
        let other_der = spki_der(&[0x2b, 0x65, 0x70], &other_raw);
        let other_pem = pem_single(base64_encode_for_test(&other_der).as_bytes());

        let a = Ed25519PublicKey::from_spki_pem(&pem_single(RFC8410_PEM_BODY.as_bytes())).unwrap();
        let b = Ed25519PublicKey::from_spki_pem(&pem_from_lines(
            &[RFC8410_PEM_BODY.as_bytes()],
            b"\r\n",
            b"\r\n",
        ))
        .unwrap();
        let c = Ed25519PublicKey::from_spki_pem(&other_pem).unwrap();

        assert_eq!(a, b);
        assert_ne!(a, c);
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};
        fn hash_of(key: &Ed25519PublicKey) -> u64 {
            let mut hasher = DefaultHasher::new();
            key.hash(&mut hasher);
            hasher.finish()
        }
        assert_eq!(hash_of(&a), hash_of(&b));
    }
