        let bom = [0xefu8, 0xbb, 0xbf];
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&[&bom[..], &valid].concat()).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 尾标记后：杂散字节、额外换行、空行、单独 CR、第二个块。
        let base = pem_of_der(RFC8410_SPKI);
        for extra in [
            &b"x"[..],
            &b"\n\n"[..],
            &b"\nmore"[..],
            &b"\r"[..],
            &b"\r\n\r\n"[..],
        ] {
