        // 裸 32 字节公钥包进 PEM：不是 SPKI 容器。
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_of_der(&RFC8410_SPKI[12..])).unwrap_err(),
            ImportPublicKeyError::Malformed
